corpos.rota_050_ajustar(p_acao text, p_cds bigi:
CREATE OR REPLACE FUNCTION public.rota_050_ajustar(p_acao text, p_cds bigint[], p_veiculo text, p_ordem jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hoje date := public.rota_050_hoje();
  v_uid uuid := auth.uid();
  v_nome text;
  v_n integer;
  v_veics text[];
begin
  if not coalesce(public.pode_marcar_rota(), false) then
    raise exception 'sem permissao para ajustar a rota' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(5100, 5001);
  if p_acao is null or p_acao not in ('remover', 'adicionar') or p_cds is null or pg_catalog.cardinality(p_cds) not between 1 and 300
     or (p_acao = 'adicionar' and p_veiculo is null) then
    raise exception 'ajuste invalido' using errcode = '22023';
  end if;
  if not exists (select 1 from public.rota_dia_fechada where data = v_hoje and estado = 'fechada') then
    raise exception 'a rota de hoje nao esta fechada' using errcode = 'P0002';
  end if;
  v_nome := public.rota_050_nome(v_uid);
  if p_acao = 'remover' then
    if (select count(*) from public.rota_dia_item i where i.data = v_hoje and i.cd_pedido = any (p_cds) and i.removido_em is null)
       <> (select count(distinct x) from pg_catalog.unnest(p_cds) x) then
      raise exception 'pedido nao esta na rota de hoje' using errcode = 'P0002';
    end if;
    if exists (select 1 from public.rota_dia_item i
                where i.data = v_hoje and i.removido_em is null and i.documento is not null and i.cd_pedido <> all (p_cds)
                  and i.documento in (select j.documento from public.rota_dia_item j where j.data = v_hoje and j.cd_pedido = any (p_cds))) then
      raise exception 'remover de hoje precisa levar todos os pedidos do cliente (atualize a aba)' using errcode = '22023';
    end if;
    select pg_catalog.array_agg(distinct i.veiculo_id) into v_veics from public.rota_dia_item i where i.data = v_hoje and i.cd_pedido = any (p_cds);
    update public.rota_dia_item set removido_em = pg_catalog.now(), removido_por = v_uid, removido_nome = v_nome, ordem = null
     where data = v_hoje and cd_pedido = any (p_cds);
  else
    if not exists (select 1 from public.rota_veiculos v where v.id = p_veiculo and v.ativo) then
      raise exception 'veiculo desativado ou inexistente' using errcode = '22023';
    end if;
    if exists (select 1 from public.rota_dia_item i where i.data = v_hoje and i.cd_pedido = any (p_cds) and i.removido_em is null) then
      raise exception 'pedido ja esta na rota de hoje' using errcode = '23505';
    end if;
    if (select count(*) from public.solidcon_pedidos_erp p where p.cd_pedido = any (p_cds)
           and public.rota_055_pendente(p.cd_pedido,public.rota_050_hoje())) <> (select count(distinct x) from pg_catalog.unnest(p_cds) x) then
      raise exception 'pedido nao esta em aberto no ERP' using errcode = 'P0002';
    end if;
    v_veics := array[p_veiculo];
    insert into public.rota_dia_item (data, cd_pedido, documento, veiculo_id, ordem, origem, incluido_por)
    select v_hoje, p.cd_pedido, p.documento, p_veiculo, null, 'adicionado', v_uid
      from public.solidcon_pedidos_erp p where p.cd_pedido = any (p_cds)
    on conflict (data, cd_pedido) do update
      set veiculo_id = excluded.veiculo_id, ordem = null, origem = 'adicionado', incluido_em = pg_catalog.now(),
          incluido_por = excluded.incluido_por, removido_em = null, removido_por = null, removido_nome = null, documento = excluded.documento;
  end if;
  -- ordem nova SO dos veiculos afetados: tem de cobrir exatamente os pedidos ativos deles
  if p_ordem is null or pg_catalog.jsonb_typeof(p_ordem) <> 'array' then
    raise exception 'ordem invalida' using errcode = '22023';
  end if;
  if exists (select 1 from pg_catalog.jsonb_array_elements(p_ordem) e
              where pg_catalog.jsonb_typeof(e -> 'cd_pedido') <> 'number' or pg_catalog.jsonb_typeof(e -> 'ordem') <> 'number'
                 or (e ->> 'ordem')::numeric not between 1 and 100000) then
    raise exception 'ordem invalida' using errcode = '22023';
  end if;
  if (select pg_catalog.array_agg(x order by x) from (select (e ->> 'cd_pedido')::bigint x from pg_catalog.jsonb_array_elements(p_ordem) e) s)
     is distinct from
     (select pg_catalog.array_agg(i.cd_pedido order by i.cd_pedido) from public.rota_dia_item i
       where i.data = v_hoje and i.veiculo_id = any (v_veics) and i.removido_em is null) then
    raise exception 'a ordem nao confere com os pedidos do veiculo (atualize a aba)' using errcode = '22023';
  end if;
  update public.rota_dia_item i set ordem = (e ->> 'ordem')::integer
    from pg_catalog.jsonb_array_elements(p_ordem) e
   where i.data = v_hoje and i.cd_pedido = (e ->> 'cd_pedido')::bigint;
  update public.rota_dia_fechada set alterada_em = pg_catalog.now(), revisao = revisao + 1 where data = v_hoje;
  v_n := pg_catalog.cardinality(p_cds);
  insert into public.rota_dia_log (data, acao, detalhe, por, por_nome)
  values (v_hoje, p_acao::text, pg_catalog.left(v_n || ' pedido(s), veiculo(s) ' || pg_catalog.array_to_string(v_veics, ',') || ': ' || pg_catalog.array_to_string(p_cds[1:20], ','), 200), v_uid, v_nome);
  return (select pg_catalog.to_jsonb(f) from public.rota_dia_fechada f where f.data = v_hoje);
end;
$function$

corpos.rota_050_envio_ok(p_data date, p_veic te:
CREATE OR REPLACE FUNCTION public.rota_050_envio_ok(p_data date, p_veic text, p_paradas jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_pub text; v_esp text; v_cd boolean;
begin
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(case when pg_catalog.jsonb_typeof(p_paradas)='array' then p_paradas else '[]'::jsonb end) par
    cross join lateral (
      select x from pg_catalog.jsonb_array_elements(case when pg_catalog.jsonb_typeof(par->'pedidos')='array' then par->'pedidos' else '[]'::jsonb end) x
      union all select x from pg_catalog.jsonb_array_elements(case when pg_catalog.jsonb_typeof(par->'itens')='array' then par->'itens' else '[]'::jsonb end) it
        cross join lateral pg_catalog.jsonb_array_elements(case when pg_catalog.jsonb_typeof(it->'pedidos')='array' then it->'pedidos' else '[]'::jsonb end) x
    ) cds
    where pg_catalog.jsonb_typeof(x)='number' and not public.rota_055_pendente((x#>>'{}')::bigint,public.rota_050_hoje())
  ) then return false;end if;
  if not exists (select 1 from public.rota_dia_fechada f where f.data = p_data and f.estado = 'fechada') then
    return true;
  end if;
  p_paradas := case when pg_catalog.jsonb_typeof(p_paradas) = 'array' then p_paradas else '[]'::jsonb end;
  v_cd := exists (select 1 from pg_catalog.jsonb_array_elements(p_paradas) p where pg_catalog.jsonb_typeof(p -> 'itens') = 'array');
  -- enviado: grupos (parada; no CD, tudo junto) na ordem das paradas; dentro do grupo, codigos em ordem
  with par as (
    select p, n, case when pg_catalog.jsonb_typeof(p -> 'ordem') = 'number' then (p ->> 'ordem')::numeric else n end o
      from pg_catalog.jsonb_array_elements(p_paradas) with ordinality t(p, n)
  ), cds as (
    select case when v_cd then 0 else par.o end o, case when v_cd then 0 else par.n end n, (x #>> '{}')::bigint cd
      from par cross join lateral (
        select e from pg_catalog.jsonb_array_elements(case when pg_catalog.jsonb_typeof(par.p -> 'pedidos') = 'array' then par.p -> 'pedidos' else '[]'::jsonb end) e
        union all
        select e from pg_catalog.jsonb_array_elements(case when pg_catalog.jsonb_typeof(par.p -> 'itens') = 'array' then par.p -> 'itens' else '[]'::jsonb end) it
          cross join lateral pg_catalog.jsonb_array_elements(case when pg_catalog.jsonb_typeof(it -> 'pedidos') = 'array' then it -> 'pedidos' else '[]'::jsonb end) e
      ) y(x)
     where pg_catalog.jsonb_typeof(x) = 'number'
  ), g as (select o, n, pg_catalog.string_agg(distinct cd::text, ',' order by cd::text) gr from cds group by o, n)
  select coalesce(pg_catalog.string_agg(gr, '|' order by o, n), '') into v_pub from g;
  -- esperado: itens ativos da foto (em aberto, nao tirados da rota), agrupados pela ordem salva
  with esp as (
    select case when v_cd then 0 else coalesce(i.ordem, 2147483647) end o, i.cd_pedido cd
      from public.rota_dia_item i
      join public.solidcon_pedidos_erp p on p.cd_pedido = i.cd_pedido and public.rota_055_pendente(p.cd_pedido,public.rota_050_hoje())
     where i.data = p_data and i.veiculo_id = p_veic and i.removido_em is null
       and not exists (select 1 from public.rota_pedido_ignorado r where r.cd_pedido = i.cd_pedido)
  ), g as (select o, pg_catalog.string_agg(cd::text, ',' order by cd::text) gr from esp group by o)
  select coalesce(pg_catalog.string_agg(gr, '|' order by o), '') into v_esp from g;
  return v_pub = v_esp;
end;
$function$

corpos.rota_050_fechar(p_itens jsonb):
CREATE OR REPLACE FUNCTION public.rota_050_fechar(p_itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not coalesce(public.pode_marcar_rota(), false) then
    raise exception 'sem permissao para fechar a rota' using errcode = '42501';
  end if;
  return public.rota_050_fechar_hoje(p_itens, auth.uid(), false);
end;
$function$

corpos.rota_050_fechar_auto(p_itens jsonb):
CREATE OR REPLACE FUNCTION public.rota_050_fechar_auto(p_itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hoje date := public.rota_050_hoje();
  v_saida time;
  v_itens jsonb;
begin
  perform pg_catalog.pg_advisory_xact_lock(5100, 5001);
  if exists (select 1 from public.rota_dia_fechada where data = v_hoje) then
    return pg_catalog.jsonb_build_object('fechou', false, 'motivo', 'ja_tem');
  end if;
  if extract(dow from v_hoje) = 0 then
    return pg_catalog.jsonb_build_object('fechou', false, 'motivo', 'sem_saida');
  end if;
  select c.hora_saida into v_saida from public.rota_config c where c.id = 1;
  if (pg_catalog.now() at time zone 'America/Sao_Paulo')::time < coalesce(v_saida, '08:00'::time) then
    return pg_catalog.jsonb_build_object('fechou', false, 'motivo', 'antes_da_hora');
  end if;
  -- Tique inicial atrasado: nao transportar criacao/separacao posterior a saida.
  -- A funcao050 interna continua validando integralmente a lista restante.
  if p_itens is null or pg_catalog.jsonb_typeof(p_itens)<>'array' or pg_catalog.jsonb_array_length(p_itens)>3000 then
    raise exception 'lista de pedidos invalida' using errcode='22023';
  end if;
  select coalesce(pg_catalog.jsonb_agg(x.e order by x.o),'[]'::jsonb) into v_itens
    from pg_catalog.jsonb_array_elements(p_itens) with ordinality x(e,o)
   where not exists(select from public.solidcon_pedidos_erp p
     where p.cd_pedido=(x.e->>'cd_pedido')::numeric
       and greatest(p.dt_pedido,p.dt_sep_inicio)>((v_hoje + pg_catalog.make_time(extract(hour from coalesce(v_saida,'08:00'::time))::integer,extract(minute from coalesce(v_saida,'08:00'::time))::integer,0)) at time zone 'America/Sao_Paulo'));
  return pg_catalog.jsonb_build_object('fechou', true, 'rota', public.rota_050_fechar_hoje(v_itens, null, true));
end;
$function$

corpos.rota_050_fechar_hoje(p_itens jsonb, p_ui:
CREATE OR REPLACE FUNCTION public.rota_050_fechar_hoje(p_itens jsonb, p_uid uuid, p_auto boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hoje date := public.rota_050_hoje();
  v_atual public.rota_dia_fechada;
  v_nome text := case when p_uid is null then null else public.rota_050_nome(p_uid) end;
  v_n integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(5100, 5001);
  if extract(dow from v_hoje) = 0 then
    raise exception 'domingo: sem saida' using errcode = '22023';
  end if;
  select * into v_atual from public.rota_dia_fechada where data = v_hoje for update;
  if found and v_atual.estado = 'fechada' then
    raise exception 'a rota de hoje ja esta fechada' using errcode = '23505';
  end if;
  if found then   -- reaberta: fecha de novo (versao + 1)
    delete from public.rota_dia_item where data = v_hoje;
    update public.rota_dia_fechada
       set estado = 'fechada', automatico = p_auto, versao = v_atual.versao + 1, revisao = v_atual.revisao + 1, fechada_em = pg_catalog.now(),
           fechada_por = p_uid, fechada_nome = v_nome, alterada_em = null
     where data = v_hoje;
  else
    insert into public.rota_dia_fechada (data, estado, automatico, fechada_por, fechada_nome)
    values (v_hoje, 'fechada', p_auto, p_uid, v_nome);
  end if;
  v_n := public.rota_050_gravar_itens(v_hoje, p_itens, p_uid);
  insert into public.rota_dia_log (data, acao, detalhe, por, por_nome)
  values (v_hoje, case when p_auto then 'fechar_auto' else 'fechar' end, v_n || ' pedido(s)', p_uid, v_nome);
  return (select pg_catalog.to_jsonb(f) from public.rota_dia_fechada f where f.data = v_hoje);
end;
$function$

corpos.rota_050_gravar_itens(p_data date, p_ite:
CREATE OR REPLACE FUNCTION public.rota_050_gravar_itens(p_data date, p_itens jsonb, p_uid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_n integer;
begin
  if p_itens is null or pg_catalog.jsonb_typeof(p_itens) <> 'array' or pg_catalog.jsonb_array_length(p_itens) > 3000 then
    raise exception 'lista de pedidos invalida' using errcode = '22023';
  end if;
  if exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e
              where pg_catalog.jsonb_typeof(e) <> 'object'
                 or pg_catalog.jsonb_typeof(e -> 'cd_pedido') <> 'number'
                 or pg_catalog.jsonb_typeof(e -> 'veiculo_id') <> 'string'
                 or (e ? 'ordem' and pg_catalog.jsonb_typeof(e -> 'ordem') not in ('number', 'null'))) then
    raise exception 'item invalido na lista de pedidos' using errcode = '22023';
  end if;
  -- sem tabela temporaria (funcao DEFINER): a lista e relida do jsonb em cada conferencia
  if exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e
              where (e ->> 'cd_pedido')::numeric not between 1 and 999999999999
                 or (e ->> 'cd_pedido')::numeric <> pg_catalog.trunc((e ->> 'cd_pedido')::numeric)
                 or (e ->> 'ordem') is not null and ((e ->> 'ordem')::numeric not between 1 and 100000
                                                     or (e ->> 'ordem')::numeric <> pg_catalog.trunc((e ->> 'ordem')::numeric))) then
    raise exception 'item invalido na lista de pedidos' using errcode = '22023';
  end if;
  if exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e group by (e ->> 'cd_pedido')::bigint having count(*) > 1) then
    raise exception 'pedido repetido na lista' using errcode = '22023';
  end if;
  if exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e
              where not exists (select 1 from public.rota_veiculos v where v.id = e ->> 'veiculo_id' and v.ativo)) then
    raise exception 'veiculo desativado ou inexistente' using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(5100, 4601);        -- 065: le o plano sem gravacao concorrente (5001 ja e nossa)
  p_itens := public.rota_065_aplicar_plano(p_data, p_itens);   -- 065: o plano salvo vale no fechamento
  -- B065-R1: fechamento AUTOMATICO (linha recem-gravada por rota_050_fechar_hoje): corte 061 sobre a lista FINAL.
  -- Ordem renumerada so quando algo saiu (dense_rank mantem paradas com varios pedidos juntas; CD/CEASA segue null).
  if coalesce((select f.automatico from public.rota_dia_fechada f where f.data = p_data), false)
     and exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e
                  where public.rota_065_pos_corte((e ->> 'cd_pedido')::bigint, p_data)) then
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('cd_pedido', r.cd, 'veiculo_id', r.v, 'ordem', r.o)
             order by r.pos), '[]'::jsonb)
      into p_itens
      from (select k.cd, k.v, k.pos,
                   case when k.o is null then null
                        else (pg_catalog.dense_rank() over (partition by k.v, k.o is null order by k.o))::integer end o
              from (select (x.e ->> 'cd_pedido')::bigint cd, x.e ->> 'veiculo_id' v, (x.e ->> 'ordem')::integer o, x.pos
                      from pg_catalog.jsonb_array_elements(p_itens) with ordinality x(e, pos)
                     where not public.rota_065_pos_corte((x.e ->> 'cd_pedido')::bigint, p_data)) k) r;
  end if;
  if exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e where not exists (
        select 1 from public.solidcon_pedidos_erp p
         where p.cd_pedido = (e ->> 'cd_pedido')::bigint and public.rota_055_pendente(p.cd_pedido,public.rota_050_hoje()))) then
    raise exception 'pedido nao esta em aberto no ERP' using errcode = 'P0002';
  end if;
  insert into public.rota_dia_item (data, cd_pedido, documento, veiculo_id, ordem, origem, incluido_por)
  select p_data, p.cd_pedido, p.documento, e ->> 'veiculo_id', (e ->> 'ordem')::integer, 'previsao', p_uid
    from pg_catalog.jsonb_array_elements(p_itens) e
    join public.solidcon_pedidos_erp p on p.cd_pedido = (e ->> 'cd_pedido')::bigint;
  get diagnostics v_n = row_count;
  return v_n;
end;
$function$

corpos.rota_050_limpar():
CREATE OR REPLACE FUNCTION public.rota_050_limpar()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_n integer;
begin
  delete from public.rota_dia_fechada where data < public.rota_050_hoje() - 60;
  get diagnostics v_n = row_count;
  delete from public.rota_dia_log where em < pg_catalog.now() - interval '180 days';
  return v_n;
end;
$function$

corpos.rota_050_publicar(p_data date, p_veiculo:
CREATE OR REPLACE FUNCTION public.rota_050_publicar(p_data date, p_veiculo text, p_paradas jsonb, p_resumo jsonb, p_revisao integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rev integer;
begin
  if not coalesce(public.pode_marcar_rota(), false) then
    raise exception 'sem permissao para enviar a rota' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(5100, 5001);
  select f.revisao into v_rev from public.rota_dia_fechada f where f.data = public.rota_050_hoje();
  if coalesce(v_rev, 0) is distinct from coalesce(p_revisao, -1) then
    raise exception 'a rota de hoje mudou (fechada, ajustada ou reaberta) depois que a tela carregou: atualize e envie de novo' using errcode = '40001';
  end if;
  if not public.rota_050_envio_ok(p_data, p_veiculo, p_paradas) then
    raise exception 'a rota de hoje foi fechada ou ajustada depois que a tela carregou: atualize e envie de novo' using errcode = '40001';
  end if;
  insert into public.rota_saida (data, veiculo_id, paradas, resumo)
  values (p_data, p_veiculo, p_paradas, p_resumo)
  on conflict (data, veiculo_id) do update set paradas = excluded.paradas, resumo = excluded.resumo;
  return (select pg_catalog.to_jsonb(r) from public.rota_saida r where r.data = p_data and r.veiculo_id = p_veiculo);
end;
$function$

corpos.rota_050_reabrir():
CREATE OR REPLACE FUNCTION public.rota_050_reabrir()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hoje date := public.rota_050_hoje();
  v_uid uuid := auth.uid();
  v_nome text;
begin
  if not coalesce(public.eh_admin(), false) then
    raise exception 'so o administrador reabre a rota' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(5100, 5001);
  if not exists (select 1 from public.rota_dia_fechada where data = v_hoje and estado = 'fechada') then
    raise exception 'a rota de hoje nao esta fechada' using errcode = 'P0002';
  end if;
  v_nome := public.rota_050_nome(v_uid);
  delete from public.rota_dia_item where data = v_hoje;
  update public.rota_dia_fechada set estado = 'reaberta', reaberta_em = pg_catalog.now(), reaberta_por = v_uid, reaberta_nome = v_nome, revisao = revisao + 1
   where data = v_hoje;
  insert into public.rota_dia_log (data, acao, detalhe, por, por_nome) values (v_hoje, 'reabrir', null, v_uid, v_nome);
  return (select pg_catalog.to_jsonb(f) from public.rota_dia_fechada f where f.data = v_hoje);
end;
$function$

corpos.rota_050_saida_conferir():
CREATE OR REPLACE FUNCTION public.rota_050_saida_conferir()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(5100, 5001);
  if not public.rota_050_envio_ok(new.data, new.veiculo_id, new.paradas) then
    raise exception 'a rota de hoje foi fechada ou ajustada depois que a tela carregou: atualize e envie de novo' using errcode = '40001';
  end if;
  return new;
end;
$function$

corpos.rota_055_canhoto_revisao():
CREATE OR REPLACE FUNCTION public.rota_055_canhoto_revisao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_cds bigint[];
begin
 if tg_op='INSERT' then select array_agg(distinct cd_pedido) into v_cds from novos where substituido_em is null;
 elsif tg_op='DELETE' then select array_agg(distinct cd_pedido) into v_cds from antigos where substituido_em is null;
 else select array_agg(distinct cd_pedido) into v_cds from
   (select cd_pedido from antigos where substituido_em is null union select cd_pedido from novos where substituido_em is null) c;
 end if;
 if v_cds is null then return null;end if;
 perform pg_catalog.pg_advisory_xact_lock(5100,5001);
 update public.rota_dia_fechada f set revisao=f.revisao+1,alterada_em=pg_catalog.now()
 where f.data=public.rota_050_hoje() and f.estado='fechada' and exists(
   select 1 from public.rota_dia_item i where i.data=f.data and i.removido_em is null and i.cd_pedido=any(v_cds));
 return null;
end$function$

corpos.rota_063_confirmar_entrega(p_cd bigint,:
CREATE OR REPLACE FUNCTION public.rota_063_confirmar_entrega(p_cd bigint, p_motivo text, p_requisicao uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare r public.pedido_entrega_confirmacao;u uuid:=auth.uid();begin
 if u is null or not coalesce(public.pode_marcar_rota(),false) then raise exception 'somente quem marca rota confirma entrega' using errcode='42501';end if;
 if p_cd is null or p_cd not between 1 and 999999999999 or p_requisicao is null or pg_catalog.length(p_motivo)>300 then
   raise exception 'confirmacao invalida' using errcode='22023';end if;
 perform pg_catalog.pg_advisory_xact_lock(5100,5201);perform pg_catalog.pg_advisory_xact_lock(5100,5001);
 select * into r from public.pedido_entrega_confirmacao where requisicao=p_requisicao;
 if found then
   if r.cd_pedido<>p_cd then raise exception 'requisicao pertence a outro pedido' using errcode='22023';end if;
   return pg_catalog.jsonb_build_object('id',r.id,'ativa',r.desfeito_em is null,'repetido',true);
 end if;
 select * into r from public.pedido_entrega_confirmacao where cd_pedido=p_cd and desfeito_em is null;
 if found then return pg_catalog.jsonb_build_object('id',r.id,'ativa',true,'repetido',true);end if;
 if not exists(select from public.solidcon_pedidos_erp p where p.cd_pedido=p_cd and p.etapa in('saiu','atendido')
   and coalesce(p.dt_saida,p.dt_nota,p.dt_atendido) is not null) then
   raise exception 'pedido nao faturado ou nao encontrado: atualize o painel' using errcode='P0002';
 end if;
 if exists(select from public.pedido_canhoto c where c.cd_pedido=p_cd and c.substituido_em is null) then
   raise exception 'pedido ja possui canhoto ativo: atualize o painel' using errcode='40001';end if;
 insert into public.pedido_entrega_confirmacao(cd_pedido,requisicao,confirmado_por,confirmado_nome,motivo)
 values(p_cd,p_requisicao,u,public.rota_050_nome(u),nullif(pg_catalog.btrim(p_motivo),'')) returning * into r;
 return pg_catalog.jsonb_build_object('id',r.id,'ativa',true,'repetido',false);
end$function$

corpos.rota_063_desfazer_entrega(p_id bigint):
CREATE OR REPLACE FUNCTION public.rota_063_desfazer_entrega(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare r public.pedido_entrega_confirmacao;u uuid:=auth.uid();begin
 if u is null or not coalesce(public.eh_admin(),false) then raise exception 'somente admin desfaz entrega' using errcode='42501';end if;
 perform pg_catalog.pg_advisory_xact_lock(5100,5201);perform pg_catalog.pg_advisory_xact_lock(5100,5001);
 select * into r from public.pedido_entrega_confirmacao where id=p_id for update;
 if not found then raise exception 'confirmacao nao encontrada' using errcode='P0002';end if;
 if r.desfeito_em is not null then return pg_catalog.jsonb_build_object('id',r.id,'ativa',false,'repetido',true);end if;
 update public.pedido_entrega_confirmacao set desfeito_por=u,desfeito_nome=public.rota_050_nome(u),desfeito_em=pg_catalog.clock_timestamp() where id=p_id;
 return pg_catalog.jsonb_build_object('id',r.id,'ativa',false,'repetido',false);
end$function$

corpos.rota_065_ler_semana(p_inicio date):
CREATE OR REPLACE FUNCTION public.rota_065_ler_semana(p_inicio date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not coalesce(public.eh_equipe(), false) then
    raise exception 'equipe necessaria' using errcode = '42501';
  end if;
  if p_inicio is null or extract(isodow from p_inicio) <> 1 then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'parametro_invalido');
  end if;
  return pg_catalog.jsonb_build_object(
    'status', 'ok', 'inicio', p_inicio, 'hoje', public.rota_050_hoje(),
    'pedidos_estado',coalesce((select jsonb_object_agg(e.cd_pedido,jsonb_build_object('entregue',public.rota_068_pedido_entregue(e.cd_pedido),'reprogramado',exists(select 1 from public.rota_068h_reprogramacao r where r.cd_pedido=e.cd_pedido and r.ativa),'data_recebimento',public.rota_068_recebido_dia(e.cd_pedido),'pendente',public.rota_055_pendente(e.cd_pedido,public.rota_068_hoje()))) from (select cd_pedido from public.solidcon_pedidos_erp union select cd_pedido from public.rota_plano_semana union select cd_pedido from public.pedido_entrega_rota union select cd_pedido from public.pedido_entrega_confirmacao) e),'{}'::jsonb),
    'versao', coalesce((select s.versao from public.rota_065_semana s where s.inicio = p_inicio), 0),
    'itens', coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('cd_pedido', p.cd_pedido, 'dia', p.dia, 'veiculo_id', p.veiculo_id,
                 'ordem', p.ordem, 'removido', p.removido) order by p.dia, p.veiculo_id, p.removido, p.ordem nulls last, p.cd_pedido)
              from public.rota_plano_semana p where p.dia between p_inicio and p_inicio + 5), '[]'::jsonb),
    'sem_saida', coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('dia', s.dia, 'veiculo_id', s.veiculo_id, 'motivo', s.motivo)
                 order by s.dia, s.veiculo_id)
              from public.rota_065_sem_saida s where s.dia between p_inicio and p_inicio + 5), '[]'::jsonb),
    'fechados', coalesce((select pg_catalog.jsonb_agg(f.data order by f.data)
              from public.rota_dia_fechada f where f.data between p_inicio and p_inicio + 5 and f.estado = 'fechada'), '[]'::jsonb));
end;
$function$

corpos.rota_065_marcar_sem_saida(p_dia date, p_:
CREATE OR REPLACE FUNCTION public.rota_065_marcar_sem_saida(p_dia date, p_veiculo text, p_sem_saida boolean, p_versao_base bigint, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_inicio date;
  v_versao bigint;
  v_motivo text := nullif(pg_catalog.btrim(p_motivo), '');
  v_devolvidos jsonb := '[]'::jsonb;
begin
  if not coalesce(public.pode_marcar_rota(), false) then
    raise exception 'sem permissao para marcar o veiculo' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(5100, 4601);
  if p_dia is null or extract(isodow from p_dia) not between 1 and 6 or p_veiculo is null or p_sem_saida is null
     or p_versao_base is null or p_versao_base < 0
     or (v_motivo is not null and (pg_catalog.char_length(v_motivo) > 80 or v_motivo ~ '[[:cntrl:]<>]')) then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'parametro_invalido');
  end if;
  if not exists (select 1 from public.rota_veiculos v where v.id = p_veiculo and v.ativo) then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'veiculo_invalido');
  end if;
  if not public.rota_065_dia_editavel(p_dia) then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'dia_bloqueado');
  end if;
  v_inicio := p_dia - (extract(isodow from p_dia)::integer - 1);
  v_versao := coalesce((select s.versao from public.rota_065_semana s where s.inicio = v_inicio), 0);
  if v_versao <> p_versao_base then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'versao_antiga', 'versao', v_versao);
  end if;
  if p_sem_saida then
    insert into public.rota_065_sem_saida as s (dia, veiculo_id, motivo, marcado_por)
    values (p_dia, p_veiculo, v_motivo, auth.uid())
    on conflict (dia, veiculo_id) do update set motivo = excluded.motivo, marcado_em = pg_catalog.now(), marcado_por = excluded.marcado_por;
    -- Pedidos programados neste veiculo/dia voltam para a bandeja (sem dia no plano).
    with apagados as (
      delete from public.rota_plano_semana p where p.dia = p_dia and p.veiculo_id = p_veiculo returning p.cd_pedido, p.removido
    ) select coalesce(pg_catalog.jsonb_agg(a.cd_pedido order by a.cd_pedido) filter (where not a.removido), '[]'::jsonb)
        into v_devolvidos from apagados a;
  else
    delete from public.rota_065_sem_saida s where s.dia = p_dia and s.veiculo_id = p_veiculo;
  end if;
  perform public.rota_065_subir(v_inicio);
  return pg_catalog.jsonb_build_object('status', 'ok', 'devolvidos', v_devolvidos,
    'versao', (select s.versao from public.rota_065_semana s where s.inicio = v_inicio));
end;
$function$

corpos.rota_065_plano_guardar():
CREATE OR REPLACE FUNCTION public.rota_065_plano_guardar()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if current_user is distinct from 'authenticated' then return case when tg_op='DELETE' then old else new end;end if;
 if (tg_op in('UPDATE','DELETE') and public.rota_068_pedido_entregue(old.cd_pedido)) or (tg_op in('INSERT','UPDATE') and public.rota_068_pedido_entregue(new.cd_pedido)) then raise exception 'pedido_historico' using errcode='22023';end if;
 if tg_op in('INSERT','UPDATE') and not public.rota_065_linha_editavel(new.dia,new.veiculo_id) then raise exception 'dia destino nao editavel' using errcode='22023';end if;
 return case when tg_op='DELETE' then old else new end;
end$function$

corpos.rota_065_plano_versao():
CREATE OR REPLACE FUNCTION public.rota_065_plano_versao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op in ('UPDATE', 'DELETE') then perform public.rota_065_subir(old.dia); end if;
  if tg_op in ('INSERT', 'UPDATE') and (tg_op = 'INSERT' or new.dia is distinct from old.dia) then perform public.rota_065_subir(new.dia); end if;
  return null;
end;
$function$

corpos.rota_065_salvar_semana(p_inicio date, p_:
CREATE OR REPLACE FUNCTION public.rota_065_salvar_semana(p_inicio date, p_versao_base bigint, p_itens jsonb, p_veiculo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_versao bigint;
  v_cd bigint;
  v_n integer; v_068_antes jsonb; v_068_cd bigint;
  v_campos constant text[] := array['cd_pedido', 'dia', 'veiculo_id', 'ordem', 'removido'];
begin
  if not coalesce(public.pode_marcar_rota(), false) then
    raise exception 'sem permissao para salvar o plano' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(5100,5201);perform pg_catalog.pg_advisory_xact_lock(5100,5001);
  perform pg_catalog.pg_advisory_xact_lock(5100, 4601);
  -- Forma: lista de objetos com exatamente as 5 chaves e os tipos do contrato.
  if p_inicio is null or extract(isodow from p_inicio) <> 1 or p_versao_base is null or p_versao_base < 0
     or p_itens is null or pg_catalog.jsonb_typeof(p_itens) <> 'array' or pg_catalog.jsonb_array_length(p_itens) > 3000
     or exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e
                 where pg_catalog.jsonb_typeof(e) <> 'object' or not (e ?& v_campos)
                    or exists (select 1 from pg_catalog.jsonb_object_keys(e) k where not (k = any (v_campos)))
                    or pg_catalog.jsonb_typeof(e -> 'cd_pedido') <> 'number' or (e ->> 'cd_pedido') !~ '^[1-9][0-9]{0,11}$'
                    or pg_catalog.jsonb_typeof(e -> 'dia') <> 'string' or (e ->> 'dia') !~ '^\d{4}-\d{2}-\d{2}$'
                    or pg_catalog.jsonb_typeof(e -> 'veiculo_id') <> 'string'
                    or pg_catalog.jsonb_typeof(e -> 'removido') <> 'boolean'
                    or (pg_catalog.jsonb_typeof(e -> 'ordem') <> 'null'
                        and (pg_catalog.jsonb_typeof(e -> 'ordem') <> 'number' or (e ->> 'ordem') !~ '^[1-9][0-9]{0,5}$'))) then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'parametro_invalido');
  end if;
  begin
    if exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e where (e ->> 'dia')::date not between p_inicio and p_inicio + 5)
       or (p_veiculo is not null and exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e where e ->> 'veiculo_id' is distinct from p_veiculo)) then
      return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'parametro_invalido');
    end if;
  exception when others then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'parametro_invalido');
  end;
  select (e ->> 'cd_pedido')::bigint into v_cd from pg_catalog.jsonb_array_elements(p_itens) e
   group by (e ->> 'cd_pedido')::bigint having count(*) > 1 order by 1 limit 1;
  if found then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'pedido_duplicado', 'cd_pedido', v_cd);
  end if;
  if (p_veiculo is not null and not exists (select 1 from public.rota_veiculos v where v.id = p_veiculo and v.ativo))
     or exists (select 1 from pg_catalog.jsonb_array_elements(p_itens) e
                 where not exists (select 1 from public.rota_veiculos v where v.id = e ->> 'veiculo_id' and v.ativo)) then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'veiculo_invalido');
  end if;
  select (e->>'cd_pedido')::bigint into v_cd from pg_catalog.jsonb_array_elements(p_itens) e where public.rota_068_pedido_entregue((e->>'cd_pedido')::bigint) limit 1;
  if found then return pg_catalog.jsonb_build_object('status','erro','motivo','pedido_historico','cd_pedido',v_cd);end if;
  select (e ->> 'cd_pedido')::bigint into v_cd from pg_catalog.jsonb_array_elements(p_itens) e
   where not public.rota_065_dia_editavel((e ->> 'dia')::date) order by 1 limit 1;
  if found then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'dia_bloqueado', 'cd_pedido', v_cd);
  end if;
  -- B065-R3: a ORIGEM tambem conta. Pedido ja salvo em linha travada (hoje, fechado, passado desta semana, veiculo
  -- inativo/sem saida) nao e movido pelo ON CONFLICT: recusa tudo, com o mesmo motivo e origem:true.
  select p.cd_pedido into v_cd from pg_catalog.jsonb_array_elements(p_itens) e
    join public.rota_plano_semana p on p.cd_pedido = (e ->> 'cd_pedido')::bigint
   where public.rota_068_pedido_entregue(p.cd_pedido) order by 1 limit 1;
  if found then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'pedido_historico', 'cd_pedido', v_cd, 'origem', true);
  end if;
  select (e ->> 'cd_pedido')::bigint into v_cd from pg_catalog.jsonb_array_elements(p_itens) e
   where not public.rota_065_sai(e ->> 'veiculo_id', (e ->> 'dia')::date) order by 1 limit 1;
  if found then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'dia_sem_saida', 'cd_pedido', v_cd);
  end if;
  select (e ->> 'cd_pedido')::bigint into v_cd from pg_catalog.jsonb_array_elements(p_itens) e
   where not exists (select 1 from public.solidcon_pedidos_erp p where p.cd_pedido = (e ->> 'cd_pedido')::bigint) order by 1 limit 1;
  if found then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'pedido_inexistente', 'cd_pedido', v_cd);
  end if;
  -- Ordem: removido e CD/CEASA = null; porta = 1..N sem buracos por (dia, veiculo).
  select (e ->> 'cd_pedido')::bigint into v_cd from pg_catalog.jsonb_array_elements(p_itens) e
    join public.rota_veiculos v on v.id = e ->> 'veiculo_id'
   where ((e ->> 'removido')::boolean or v.modo = 'cd_ceasa') and e -> 'ordem' <> 'null'::jsonb
      or not (e ->> 'removido')::boolean and v.modo = 'porta' and e -> 'ordem' = 'null'::jsonb
   order by 1 limit 1;
  if found then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'ordem_invalida', 'cd_pedido', v_cd);
  end if;
  if exists (select 1 from (
        select count(*) n, count(distinct (e ->> 'ordem')::integer) d, max((e ->> 'ordem')::integer) mx
          from pg_catalog.jsonb_array_elements(p_itens) e join public.rota_veiculos v on v.id = e ->> 'veiculo_id'
         where v.modo = 'porta' and not (e ->> 'removido')::boolean
         group by e ->> 'dia', e ->> 'veiculo_id') g where g.n <> g.d or g.mx <> g.n) then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'ordem_invalida');
  end if;
  -- Concorrencia: so grava sobre a versao que o quadro leu (o lock acima serializa com 046/047/065).
  v_versao := coalesce((select s.versao from public.rota_065_semana s where s.inicio = p_inicio), 0);
  if v_versao <> p_versao_base then
    return pg_catalog.jsonb_build_object('status', 'erro', 'motivo', 'versao_antiga', 'versao', v_versao);
  end if;
  -- B065-R3: so linha editavel COMPLETA (dia + veiculo ativo que sai); as outras ficam como estao.
  select coalesce(jsonb_object_agg(p.cd_pedido,jsonb_build_object('dia',p.dia,'veiculo_id',p.veiculo_id,'removido',p.removido)),'{}'::jsonb) into v_068_antes from public.rota_plano_semana p where (p.dia between p_inicio and p_inicio+5 and (p_veiculo is null or p.veiculo_id=p_veiculo)) or p.cd_pedido in(select (e->>'cd_pedido')::bigint from jsonb_array_elements(p_itens) e);
  delete from public.rota_plano_semana p
   where p.dia between p_inicio and p_inicio + 5 and public.rota_065_linha_editavel(p.dia, p.veiculo_id) and not public.rota_068_pedido_entregue(p.cd_pedido)
     and (p_veiculo is null or p.veiculo_id = p_veiculo);
  insert into public.rota_plano_semana as r (cd_pedido, dia, veiculo_id, ordem, removido)
  select (e ->> 'cd_pedido')::bigint, (e ->> 'dia')::date, e ->> 'veiculo_id', (e ->> 'ordem')::integer, (e ->> 'removido')::boolean
    from pg_catalog.jsonb_array_elements(p_itens) e
  on conflict (cd_pedido) do update set dia = excluded.dia, veiculo_id = excluded.veiculo_id, ordem = excluded.ordem, removido = excluded.removido;
  get diagnostics v_n = row_count;
  for v_068_cd in select distinct cd from (select key::bigint cd from jsonb_each(v_068_antes) union all select (e->>'cd_pedido')::bigint from jsonb_array_elements(p_itens) e) z loop
   if coalesce(v_068_antes->v_068_cd::text,'null'::jsonb) is distinct from coalesce((select jsonb_build_object('dia',p.dia,'veiculo_id',p.veiculo_id,'removido',p.removido) from public.rota_plano_semana p where p.cd_pedido=v_068_cd),'null'::jsonb) and not public.rota_068_pedido_entregue(v_068_cd) then
    perform public.rota_068_reprogramar_explicito(v_068_cd,(select case when not p.removido then p.dia end from public.rota_plano_semana p where p.cd_pedido=v_068_cd),(select p.veiculo_id from public.rota_plano_semana p where p.cd_pedido=v_068_cd));
   end if;
  end loop;
  perform public.rota_065_subir(p_inicio);   -- sobe mesmo salvando igual/vazio: quem leu antes relê
  return pg_catalog.jsonb_build_object('status', 'ok', 'itens', v_n,
    'versao', (select s.versao from public.rota_065_semana s where s.inicio = p_inicio));
end;
$function$

corpos.rota_068_estados_pedidos(p_cds bigint[]):
CREATE OR REPLACE FUNCTION public.rota_068_estados_pedidos(p_cds bigint[])
 RETURNS TABLE(cd_pedido bigint, entregue boolean, reprogramado boolean, data_recebimento date, pendente boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if auth.uid() is null or not coalesce(public.eh_equipe(),false) then raise exception 'somente equipe le estado' using errcode='42501';end if;
 if p_cds is null or cardinality(p_cds)>300 or exists(select 1 from unnest(p_cds) c where c is null or c not between 1 and 999999999999) then raise exception 'pedidos invalidos' using errcode='22023';end if;
 return query select distinct c,public.rota_068_pedido_entregue(c),exists(select 1 from public.rota_068h_reprogramacao r where r.cd_pedido=c and r.ativa),public.rota_068_recebido_dia(c),public.rota_055_pendente(c,public.rota_068_hoje()) from unnest(p_cds) c;
end$function$

corpos.rota_068_mover_pedido(p_cd_pedido bigint:
CREATE OR REPLACE FUNCTION public.rota_068_mover_pedido(p_cd_pedido bigint, p_dia date, p_veiculo text, p_requisicao uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare oldp public.rota_plano_semana;tem boolean;v text;modo text;ord integer;ori jsonb;dest jsonb;res jsonb;inp jsonb;
 prev public.rota_068h_movimento_log;ini date;v_old bigint;
begin
 if auth.uid() is null or not coalesce(public.pode_marcar_rota(),false) then raise exception 'sem permissao mover' using errcode='42501';end if;
 if p_cd_pedido is null or p_cd_pedido not between 1 and 999999999999 or p_requisicao is null then return jsonb_build_object('status','erro','motivo','parametro_invalido');end if;
 perform pg_advisory_xact_lock(5100,5201);perform pg_advisory_xact_lock(5100,5001);perform pg_advisory_xact_lock(5100,4601);
 inp:=jsonb_build_object('cd_pedido',p_cd_pedido,'dia',p_dia,'veiculo',p_veiculo);
 select * into prev from public.rota_068h_movimento_log where requisicao=p_requisicao;
 if found then
  if prev.entrada<>inp then return jsonb_build_object('status','erro','motivo','requisicao_invalida');end if;
  return prev.resultado||jsonb_build_object('repetido',true,'entregue',public.rota_068_pedido_entregue(p_cd_pedido));
 end if;
 if public.rota_068_pedido_entregue(p_cd_pedido) then return jsonb_build_object('status','erro','motivo','pedido_historico','entregue',true);end if;
 if not exists(select 1 from public.solidcon_pedidos_erp e where e.cd_pedido=p_cd_pedido) then return jsonb_build_object('status','erro','motivo','pedido_nao_encontrado');end if;
 select * into oldp from public.rota_plano_semana where cd_pedido=p_cd_pedido for update;tem:=found;
 v:=coalesce(p_veiculo,case when tem then oldp.veiculo_id end,
 (select m.veiculo from public.rota_pedido_veiculo m where m.cd_pedido=p_cd_pedido),
 (select c.veiculo from public.rota_cliente_veiculo c join public.solidcon_pedidos_erp e on e.documento=c.documento where e.cd_pedido=p_cd_pedido),public.rota_054_padrao_separando());
 if not exists(select 1 from public.rota_veiculos z where z.id=v and z.ativo) then return jsonb_build_object('status','erro','motivo','veiculo_invalido');end if;
 if p_dia is not null then
  if p_dia not between date '2020-01-01' and date '2100-12-31' or extract(isodow from p_dia)=7 or not public.rota_065_dia_editavel(p_dia) then return jsonb_build_object('status','erro','motivo','dia_bloqueado');end if;
  if not public.rota_065_sai(v,p_dia) then return jsonb_build_object('status','erro','motivo','dia_sem_saida');end if;
 end if;
 if tem then
  ini:=oldp.dia-(extract(isodow from oldp.dia)::integer-1);
  ori:=jsonb_build_object('dia',oldp.dia,'veiculo_id',oldp.veiculo_id,'inicio',ini);
 end if;
 perform public.rota_068_reprogramar_explicito(p_cd_pedido,p_dia,v);
 if p_dia is null then delete from public.rota_plano_semana where cd_pedido=p_cd_pedido;
 else
  select z.modo into modo from public.rota_veiculos z where z.id=v;
  if modo='porta' then select coalesce(max(p.ordem),0)+1 into ord from public.rota_plano_semana p where p.dia=p_dia and p.veiculo_id=v and not p.removido and p.cd_pedido<>p_cd_pedido;end if;
  insert into public.rota_plano_semana as p(cd_pedido,dia,veiculo_id,ordem,removido) values(p_cd_pedido,p_dia,v,ord,false)
  on conflict(cd_pedido) do update set dia=excluded.dia,veiculo_id=excluded.veiculo_id,ordem=excluded.ordem,removido=false;
  perform public.rota_068h_ordenar(p_dia,v);
 end if;
 if tem and public.rota_065_linha_editavel(oldp.dia,oldp.veiculo_id) then perform public.rota_068h_ordenar(oldp.dia,oldp.veiculo_id);end if;
 if p_veiculo is not null then insert into public.rota_pedido_veiculo as m(cd_pedido,veiculo) values(p_cd_pedido,v) on conflict(cd_pedido) do update set veiculo=excluded.veiculo;end if;
 if tem then ori:=ori||jsonb_build_object('versao',coalesce((select s.versao from public.rota_065_semana s where s.inicio=ini),0));end if;
 if p_dia is not null then
  ini:=p_dia-(extract(isodow from p_dia)::integer-1);
  dest:=jsonb_build_object('dia',p_dia,'veiculo_id',v,'inicio',ini,'versao',coalesce((select s.versao from public.rota_065_semana s where s.inicio=ini),0));
 end if;
 res:=jsonb_build_object('status','ok','entregue',false,'reprogramado',true,'origem',ori,'destino',dest,'repetido',false);
 insert into public.rota_068h_movimento_log(requisicao,cd_pedido,entrada,resultado,por) values(p_requisicao,p_cd_pedido,inp,res,auth.uid());
 return res;
end$function$

